import * as T from 'three';import {createCurlingModel,CURLING_PHYSICS as G} from './curling-model.js';import {createCurlingSession,fitCurlingCamera} from './curling-session.js';
export const CURLING_BODY=`<div class="gym-layout"><div class="gym-court" id="curling-court" role="img" aria-label="원래 도름이가 두 발을 딛고 손잡이를 밀어 스톤을 놓는 모습" tabindex="0"></div><section class="gym-panel curling-panel" id="curling-panel"><p id="curling-status" role="status"></p><div class="gym-actions"><button id="curling-start">혼자 연습 시작</button><button id="curling-pause">잠깐 쉬기</button><button id="curling-exit">정리하고 나오기</button></div><div id="curling-map" aria-label="전체 레인과 실제 스톤 위치"></div><p id="curling-contact" role="status"></p><label>방향 <input id="curling-aim" type="range" min="-0.14" max="0.14" step="0.005" value="0" aria-label="놓을 방향"></label><label>힘 <input id="curling-power" type="range" min="0.15" max="1" step="0.01" value="0.75" aria-label="놓을 힘"></label><div class="gym-hold"><button id="curling-hold">누르는 동안 힘 모으기</button><button id="curling-release">놓기</button></div><div class="gym-actions"><button id="curling-view">스톤 따라보기</button><button id="curling-reset">새 연습</button></div><p id="curling-score" role="status"></p><details id="curling-help"><summary>안내 보기</summary><p>방향과 힘을 고르고 놓아요. 원래 손에 든 짧은 스틱으로 손잡이를 밀어요. 두 발을 번갈아 딛고 민 뒤 스틱을 들어 올려요. 놓은 뒤에는 마찰과 부딪힘으로만 움직여요. 파란 스톤 네 개로 가운데 가까이 보내거나 노란 연습 스톤을 밀어 보세요.</p><p>← → 방향 · ↑ ↓ 힘 · 스페이스를 누르다 놓으면 던져요. 버튼으로 힘을 고른 뒤 ‘놓기’만 눌러도 같은 규칙이에요. 취소된 터치는 던지지 않아요.</p><p>손과 스틱을 빼는 출발길이 막히면 스톤을 쓰지 않고 기다려요. 방향이나 힘을 바꾸고, 출발 자리까지 막혔다면 ‘새 연습’으로 정리해 주세요.</p><p>전체 위치 안내는 실제 스톤 위치예요. ‘스톤 따라보기’를 직접 고르면 먼 스톤을 크게 볼 수 있어요. ‘도름이 보기’로 돌아와요. 중앙 거리와 점수는 모든 스톤이 멈춘 뒤에만 정해져요.</p><p>나가기는 움직이는 스톤을 그 자리에서 멈춰 연습을 취소하고 걸어 나와요. 저장되는 점수나 보상은 없어요. 거북이와 번갈아 하기는 아직 준비 중이에요.</p></details></section></div>`;
export function createCurlingController({ui,getView,getActors,stage,isAllowed=()=>true,onChange=()=>{},clearInput=()=>{},doc=globalThis.document,win=globalThis.window,sessionFactory=createCurlingSession,modelFactory=createCurlingModel,fitCamera=fitCurlingCamera}){
 const camera=new T.OrthographicCamera(),$=id=>doc.querySelector('#'+id);let live=null,pending=false,generation=0;
 function listen(node,type,fn,opts){if(!node)return;node.addEventListener(type,fn,opts);live.listeners.push([node,type,fn,opts]);}
 function clear(){clearInput();if(!live)return;live.pointers.clear();live.keys.clear();live.model.setInput({held:false});}
 function held(){if(live)live.model.setInput({held:live.pointers.size>0||live.keys.size>0});}
 function render(){if(!live)return;const s=live.model.snapshot(),p=live.session.phase,paused=live.suspended||s.paused,aiming=s.state==='aiming'&&live.session.ready&&!paused&&!live.exiting,ready=live.session.ready&&['ready','idle','settled','complete'].includes(s.state);
 $('curling-status').textContent=paused?'멈췄어요. 계속하기를 누르면 이어져요':p==='boarding'?'레인 앞으로 두 발을 딛고 걸어가요':live.exiting?'스톤을 정리했어요. 천천히 걸어 나와요':s.error||({idle:'손잡이를 준비해요',ready:'준비됐어요. 시작을 눌러 주세요',aiming:`${s.released+1}번째 스톤 · 방향과 힘을 골라요`,delivery:'손잡이를 밀어 놓아요',sliding:'마찰과 부딪힘으로 움직여요',settled:'모두 멈췄어요. 다음 스톤을 골라요',complete:'네 번의 연습이 끝났어요'})[s.state]||'';
 $('curling-start').disabled=!ready||paused||live.exiting;$('curling-start').textContent=s.state==='settled'?'다음 스톤':s.state==='complete'?'한 번 더':'혼자 연습 시작';$('curling-pause').textContent=paused?'계속하기':'잠깐 쉬기';$('curling-exit').disabled=live.exiting;for(const id of['aim','power','hold','release'])$('curling-'+id).disabled=!aiming;$('curling-aim').value=String(s.aim);$('curling-power').value=String(s.power);$('curling-reset').disabled=paused||live.exiting||['idle','delivery','sliding'].includes(s.state);$('curling-view').disabled=!s.released||live.exiting;$('curling-view').textContent=live.follow?'도름이 보기':'스톤 따라보기';
 const player=s.results.filter(r=>r.team==='player'),nearest=player[0];$('curling-score').textContent=nearest?`가장 가까운 파란 스톤 ${nearest.distance.toFixed(2)} m · 하우스 안 ${player.filter(r=>r.points>0).length}개 · ${player.reduce((n,r)=>n+r.points,0)}점`:`힘 ${Math.round(s.power*100)}% · 남은 파란 스톤 ${s.remaining}개`;
 $('curling-contact').textContent=s.lastContact?`${s.lastContact.type==='stone'?'스톤끼리 닿았어요':'레인 턱에 닿았어요'} · 중앙까지 ${Math.hypot(s.lastContact.x,s.lastContact.z-G.house.z).toFixed(1)} m`:live.follow?'스톤을 크게 보고 있어요':'전체 레인 위치 · 파랑은 내 스톤, 노랑은 연습 스톤';
 const x=z=>10+(z-G.minZ)/(G.maxZ-G.minZ)*260,y=a=>35-a/2.05*24;const markers=s.stones.map(a=>`<circle cx="${x(a.z).toFixed(2)}" cy="${y(a.x).toFixed(2)}" r="4" fill="${a.team==='player'?'#376ba1':'#ab761b'}" stroke="#fff" stroke-width="1"/>`).join('');$('curling-map').innerHTML=`<svg viewBox="0 0 280 70" role="img" aria-label="실제 스톤 위치"><rect x="4" y="7" width="272" height="56" rx="5" fill="#e8f1ea" stroke="#719f95"/><ellipse cx="${x(17)}" cy="35" rx="21" ry="19" fill="#a4c8cc"/><ellipse cx="${x(17)}" cy="35" rx="6" ry="5" fill="#ce947c"/>${markers}</svg>`;
 }
 function clean({restore}={}){pending=false;generation++;if(!live)return;const old=live;live=null;old.observer?.disconnect();for(const[n,t,f,o]of old.listeners)n.removeEventListener(t,f,o);old.model.dispose?.();old.session.dispose({restore:restore??(getView()===old.source)});stage.classList.remove('gym-open');doc.body?.classList.remove('gym-open');clearInput();onChange();}
 function cancel(){const owned=!!live||pending;clean();if(owned)ui.close();}
 function close(){if(!live||live.exiting)return;clear();live.suspended=false;live.model.resume();live.exiting=true;live.model.cancel();live.session.requestExit(live.model);render();}
 function pause(){if(!live)return;clear();live.suspended=true;live.model.pause();live.session.pause?.();render();}
 function open(){if(live||pending||!isAllowed())return false;const source=getView();if(!source?.schoolView?.gymView?.curling)return false;pending=true;const token=++generation;
 const accepted=ui.workshop('컬링 · 혼자 스톤 연습',CURLING_BODY,()=>{if(token!==generation||!pending)return;if(getView()!==source){pending=false;return;}pending=false;let session;try{session=sessionFactory({view:source,...getActors()});live={session,model:modelFactory(),source,listeners:[],pointers:new Set(),keys:new Set(),suspended:false,exiting:false,follow:false,fit:'',cancelledPointer:false};stage.classList.add('gym-open');doc.body?.classList.add('gym-open');clearInput();onChange();
  const act=(id,fn)=>listen($(id),'click',e=>{if(token!==generation||!live||$(id).disabled)return;if(e.detail>0&&live.cancelledPointer)return;e.preventDefault();fn();});
  act('curling-start',()=>{clear();live.follow=false;live.fit='';if(live.session.ready){live.model.start();live.session.prepareTurn?.(live.model);}render();});act('curling-reset',()=>{clear();live.follow=false;live.fit='';live.model.restart();live.session.prepareTurn?.(live.model);render();});act('curling-exit',close);act('curling-release',()=>{clear();live.model.release();render();});act('curling-view',()=>{live.follow=!live.follow;live.fit='';viewport(stage.clientWidth,stage.clientHeight);render();});
  act('curling-pause',()=>{if(doc.hidden)return;if(live.suspended||live.model.snapshot().paused){clear();live.suspended=false;live.model.resume();render();}else pause();});
  for(const field of['aim','power'])listen($('curling-'+field),'input',()=>{clear();live.model.setInput({[field]:Number($('curling-'+field).value)});render();});
  const button=$('curling-hold');listen(button,'pointerdown',e=>{if(button.disabled||e.button!==0||e.isPrimary===false||live.pointers.size)return;e.preventDefault();live.cancelledPointer=false;button.setPointerCapture?.(e.pointerId);live.pointers.add(e.pointerId);held();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(!live)return;const owned=live.pointers.delete(e.pointerId);if(type!=='pointerup')live.cancelledPointer=true;held();if(owned&&type==='pointerup'&&!live.suspended){live.model.release();render();}});
  // Keyboard/assistive activation can toggle charge; the separate release button is always available.
  act('curling-hold',()=>{const s=live.model.snapshot();if(s.held){clear();live.model.release();}else{live.keys.add('assist');held();}render();});
  listen(doc,'keydown',e=>{if(!live||e.repeat||e.ctrlKey||e.altKey||e.metaKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;const control=e.target?.closest?.('button,a,summary,[role="button"]')??(['BUTTON','A','SUMMARY'].includes(e.target?.tagName)?e.target:null);if(control&&control!==button)return;const s=live.model.snapshot();if(live.suspended||s.paused||live.exiting||!live.session.ready||s.state!=='aiming')return;if(e.code==='Space'){e.preventDefault();live.keys.add(e.code);held();}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.code)){e.preventDefault();live.model.setInput(e.code==='ArrowLeft'?{aim:s.aim-.01}:e.code==='ArrowRight'?{aim:s.aim+.01}:e.code==='ArrowUp'?{power:s.power+.05}:{power:s.power-.05});render();}});
  listen(doc,'keyup',e=>{if(!live)return;const owned=live.keys.delete(e.code);held();if(owned&&e.code==='Space'&&!live.suspended){e.preventDefault();live.model.release();render();}});
  listen($('curling-panel'),'pointerdown',()=>{if(live)live.cancelledPointer=false;},true);listen($('curling-panel'),'pointercancel',()=>{if(live)live.cancelledPointer=true;},true);
  const modal=$('modal'),exit=modal?.querySelector?.('[data-close]');if(exit)exit.onclick=e=>{e.preventDefault();close();};listen(modal,'cancel',e=>{e.preventDefault();close();});listen(modal,'click',e=>{if(e.target===modal){e.preventDefault();e.stopImmediatePropagation?.();}},true);
  listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});listen(win,'pagehide',cancel);const resize=()=>{if(live&&token===generation)viewport(stage.clientWidth,stage.clientHeight);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('curling-court'));}render();resize();$('curling-court').focus();return()=>{if(token===generation)clean();};
 }catch(error){if(live)clean();else session?.dispose();pending=false;ui.close();ui.toast('컬링 레인 앞에 빈자리가 필요해요. 잠깐 뒤 다시 해 주세요');}},{kind:'gym-workshop curling-workshop',closeLabel:'정리하고 나오기'});if(!accepted&&token===generation)pending=false;return accepted;}
 function runtimeFailure(){const restore=!!live&&getView()===live.source;clean({restore});ui.close();ui.toast('컬링 연습을 멈췄어요. 잠깐 뒤 다시 해 주세요');}
 function tick(dt){if(!live)return;if(getView()!==live.source){clean({restore:false});ui.close();return;}try{const s=live.model.snapshot();if(!live.suspended&&!s.paused){if(live.session.ready&&s.state==='idle')live.model.ready();live.session.tick(dt,live.model);if(live.session.ready&&live.model.snapshot().state==='idle')live.model.ready();}if(live.session.done){clean();ui.close();return;}render();viewport(stage.clientWidth,stage.clientHeight);}catch(error){runtimeFailure();}}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('curling-court').getBoundingClientRect(),a=stage.getBoundingClientRect(),rect={x:Math.max(0,b.left-a.left),y:Math.max(0,b.top-a.top),width:Math.max(1,Math.min(b.width,width)),height:Math.max(1,Math.min(b.height,height))},s=live.model.snapshot(),stone=s.stones.find(a=>a.id===s.released+1),key=Object.values(rect).join(',')+','+live.follow+','+live.session.phase+','+(live.follow?stone?.z:'');if(key!==live.fit){try{fitCamera(camera,live.session.root,rect,{follow:live.follow,stone,phase:live.session.phase});live.fit=key;}catch(error){runtimeFailure();}}return rect;}
 return{open,close,cancel,pause,tick,viewport,camera,dispose:cancel,get active(){return!!live;},snapshot:()=>live?{...live.model.snapshot(),paused:live.suspended||live.model.snapshot().paused,session:live.session.snapshot(),exiting:live.exiting,follow:live.follow}:null};
}
